"""Generators for `FUZZ-04`, `FUZZ-06` and `FUZZ-07`, plus the one reference model worth having.

Test plan §6.7 states each case's generator in its own **Generator / corpus** column, and that
column is a contract on this file as much as the invariant column is on the tests:

* `FUZZ-04` — *"Generated JSON: valid; field-permuted; missing fields; extra fields; wrong
  types; truncated mid-token; deeply nested; enormous strings"* (added with #83)
* `FUZZ-06` — *"Generated criterion graphs up to 30 nodes, cyclic and acyclic; generated work-ID
  input tuples"*
* `FUZZ-07` — *"Generated byte strings; generated interleavings of result and status writes"*

**Why the generators are asserted on directly, in green tests, today.** Both cases are written
ahead of every module they touch, so `require()` raises before the test body runs and the
strategies are never exercised. That leaves the generators as the untested half of a written-ahead
property test — and a degenerate strategy (only acyclic graphs, only one varying field, only
short byte strings) produces a case that passes **vacuously** the day someone removes the marker.
Nothing would say so: the property holds over a corpus that never contained a counterexample.

So `test_fuzz_generators.py` asserts the corpus has the shape §6.7 names, **over these
strategies** — the ones the fuzz cases actually draw from. An earlier draft asserted over a
parallel set of seeded samplers instead, on the false premise that `require()` runs before the
draw. It does not: `require()` is called inside the test body, after hypothesis has already drawn,
so the strategies do run today. Review measured the consequence — six degeneracies applied to the
strategies (only DAGs, one-node graphs, empty blobs, pairs differing in all nine fields) all
survived nine green generator tests, because nothing asserted about the code under test.

One reference model lives here too — `topological_order`. That property is the one that is easy to
express *backwards*: asserting `order.index(a) > order.index(b)` when the edge means `a` must come
first passes against a reversed implementation and fails against a correct one. Kahn's algorithm
and a deliberately reversed variant make the expression checkable now. The other three properties
need no model: `sha256` injectivity and a dict round-trip are tautologies, and a crash-point
simulator for transaction atomicity would be a substantial program whose own correctness nothing
checks.
"""

from __future__ import annotations

import json
import random
from dataclasses import dataclass
from typing import Sequence

from hypothesis import strategies as st

#: §6.7: *"criterion graphs up to 30 nodes"*. The ceiling is the plan's, not a tuning knob.
MAX_GRAPH_NODES = 30

#: `CT-ORCH-01`'s input set, verbatim and ordered. `FR-ORCH-01` computes `work_id` as a hash over
#: exactly these nine, and the design calls changing the set **breaking** — it invalidates every
#: stored result. Transcribed here rather than read from `aeh.orch`, so the generator asserts about
#: the design rather than agreeing with whatever the module happens to hash.
WORK_ID_FIELDS: tuple[str, ...] = (
    "run_id",
    "stage",
    "submission_id",
    "criterion_id",
    "judge_id",
    "package_version_id",
    "panel_config",
    "prompt_template_version",
    "extractor_version",
)

#: The stages a work unit can be enumerated for (design §3.9's `Stage`).
STAGES: tuple[str, ...] = ("extract", "judge", "synthesize", "deterministic", "integrity")


@dataclass(frozen=True)
class CriterionGraph:
    """A criterion dependency graph, as `FR-PKG-05` sees one: nodes plus directed edges.

    `edges` are `(before, after)` — `before` must be extracted before `after`, which is the
    direction `topological_order` has to satisfy. Stated once, here, because getting it backwards
    is the failure mode the reference model exists to catch.
    """

    nodes: tuple[str, ...]
    edges: tuple[tuple[str, str], ...]

    @property
    def is_cyclic(self) -> bool:
        return topological_order(self) is None


def topological_order(graph: CriterionGraph) -> list[str] | None:
    """Kahn's algorithm. `None` when the graph is cyclic.

    The **reference model**, used to prove the property expression in `FUZZ-06` is the right way
    round before any implementation exists. Not a substitute for `PackageCatalog.topological_order`
    — it is what the assertion is calibrated against.
    """
    incoming = {node: 0 for node in graph.nodes}
    outgoing: dict[str, list[str]] = {node: [] for node in graph.nodes}
    for before, after in graph.edges:
        outgoing[before].append(after)
        incoming[after] += 1

    ready = sorted(node for node, count in incoming.items() if count == 0)
    order: list[str] = []
    while ready:
        node = ready.pop(0)
        order.append(node)
        for successor in outgoing[node]:
            incoming[successor] -= 1
            if incoming[successor] == 0:
                ready.append(successor)
        ready.sort()

    return order if len(order) == len(graph.nodes) else None


def reversed_topological_order(graph: CriterionGraph) -> list[str] | None:
    """The **negative control**: a plausible off-by-direction implementation.

    Someone who reads `(before, after)` as "after depends on before, so emit `after` first" writes
    this. It is a legal ordering of the reversed graph and satisfies no edge of the real one, and
    a property asserted in the wrong direction cannot tell the two apart.
    """
    order = topological_order(
        CriterionGraph(nodes=graph.nodes, edges=tuple((b, a) for a, b in graph.edges))
    )
    return order


def satisfies_every_edge(order: Sequence[str], graph: CriterionGraph) -> bool:
    """`FUZZ-06`'s stated invariant: *"`topological_order` always satisfies every edge"*.

    **Length is checked, not only the set.** `position` is a dict comprehension, so a repeated node
    silently keeps its last index and `set(order) == set(nodes)` still holds: review showed
    `['a', 'a', 'b', 'b']` accepted for the edge `(a, b)`, which makes
    `lambda g: [n for n in kahn(g) for _ in range(2)]` a third wrong implementation the
    positive/negative control pair does not exclude. `M-ORCH` enumerates one work unit per
    criterion from this order, so a duplicating implementation produces duplicate units.
    """
    if len(order) != len(graph.nodes):
        return False
    position = {node: index for index, node in enumerate(order)}
    if set(position) != set(graph.nodes):
        return False
    return all(position[before] < position[after] for before, after in graph.edges)


def duplicating_topological_order(graph: CriterionGraph) -> list[str] | None:
    """A **second negative control**: a correct order with every node emitted twice.

    Direction-correct, set-correct, and wrong. It exists because review found it slipping past the
    invariant, and a control is how that stays fixed.
    """
    order = topological_order(graph)
    return None if order is None else [node for node in order for _ in range(2)]


# --- strategies --------------------------------------------------------------------------------


#: The most edges a generated graph carries. At 30 nodes there are 435 forward-pointing pairs, and
#: drawing a boolean for each made one 200-graph corpus cost ~87,000 draws — slow enough that
#: hypothesis reported a health-check failure before the assertions ran. Edges are sampled from the
#: legal pairs instead, which is a handful of draws and produces the same shapes.
MAX_GRAPH_EDGES = 40


def _forward_pairs(count: int) -> list[tuple[int, int]]:
    """Every `(earlier, later)` index pair. Edges drawn from here point forward, so a graph built
    from them is acyclic by construction — a `filter` on cyclicity would discard most draws at 30
    nodes and shrink to something unreadable."""
    return [(earlier, later) for later in range(1, count) for earlier in range(later)]


@st.composite
def acyclic_graphs(draw, max_nodes: int = MAX_GRAPH_NODES) -> CriterionGraph:
    """A DAG: nodes in a fixed order, every edge pointing forward."""
    count = draw(st.integers(min_value=1, max_value=max_nodes))
    nodes = tuple(f"c{index:02d}" for index in range(count))
    pairs = _forward_pairs(count)
    chosen: list[tuple[int, int]] = []
    if pairs:
        chosen = draw(
            st.lists(
                st.sampled_from(pairs),
                max_size=min(len(pairs), MAX_GRAPH_EDGES),
                unique=True,
            )
        )
    return CriterionGraph(
        nodes=nodes, edges=tuple((nodes[a], nodes[b]) for a, b in chosen)
    )


@st.composite
def cyclic_graphs(draw, max_nodes: int = MAX_GRAPH_NODES) -> CriterionGraph:
    """A graph guaranteed to contain at least one cycle.

    Built by taking a DAG and adding one back-edge, so the cycle sits inside a realistic graph
    rather than being a two-node loop every time — `FR-PKG-05` rejects a write that *would make*
    the graph cyclic, and the interesting case is the edge that closes a long path.
    """
    count = draw(st.integers(min_value=2, max_value=max_nodes))
    nodes = tuple(f"c{index:02d}" for index in range(count))
    pairs = _forward_pairs(count)
    chosen = draw(
        st.lists(st.sampled_from(pairs), max_size=min(len(pairs), MAX_GRAPH_EDGES), unique=True)
    )
    edges = [(nodes[a], nodes[b]) for a, b in chosen]

    # The back-edge, plus the forward edge it closes over, so the cycle sits inside a real path
    # rather than being the same two-node loop every time.
    end = draw(st.integers(min_value=1, max_value=count - 1))
    start = draw(st.integers(min_value=0, max_value=end - 1))
    if (nodes[start], nodes[end]) not in edges:
        edges.append((nodes[start], nodes[end]))
    edges.append((nodes[end], nodes[start]))
    return CriterionGraph(nodes=nodes, edges=tuple(edges))


def criterion_graphs(max_nodes: int = MAX_GRAPH_NODES):
    """Both kinds, as §6.7 asks — *"cyclic and acyclic"*."""
    return st.one_of(acyclic_graphs(max_nodes), cyclic_graphs(max_nodes))


#: Field values kept to a small pool per field, deliberately.
#:
#: `FUZZ-06`'s invariant is *"distinct input tuples always yield distinct `work_id`s"*, so the
#: corpus has to contain tuples that differ in **one** field and agree in the other eight — which
#: is what catches an implementation that drops a field from the hash. Drawing free-form text per
#: field makes every tuple differ everywhere and tests nothing but sha256.
_FIELD_POOL: dict[str, tuple[str, ...]] = {
    "run_id": ("run-a", "run-b"),
    "stage": STAGES[:2],
    "submission_id": ("sub-1", "sub-2"),
    "criterion_id": ("crit-1", "crit-2"),
    "judge_id": ("judge-1", "judge-2"),
    "package_version_id": ("pkg-v1", "pkg-v2"),
    "panel_config": ("pbr:aaaa", "pbr:bbbb"),
    "prompt_template_version": ("tmpl-v1", "tmpl-v2"),
    "extractor_version": ("extract-v1", "extract-v2"),
}


@st.composite
def work_id_inputs(draw) -> dict[str, str]:
    """One `work_id` input tuple, as a mapping keyed by `CT-ORCH-01`'s field names."""
    return {field: draw(st.sampled_from(_FIELD_POOL[field])) for field in WORK_ID_FIELDS}


@st.composite
def work_id_input_pairs(draw) -> tuple[dict[str, str], dict[str, str], str]:
    """Two tuples differing in **exactly one** field, plus the name of that field.

    This is the shape the invariant needs. A pair differing everywhere proves nothing about any
    individual input; a pair differing in `extractor_version` alone proves that input reaches the
    hash, and `CT-ORCH-01` says every one of the nine is contract.
    """
    base = draw(work_id_inputs())
    field = draw(st.sampled_from(WORK_ID_FIELDS))
    alternatives = [v for v in _FIELD_POOL[field] if v != base[field]]
    other = dict(base)
    other[field] = draw(st.sampled_from(alternatives))
    return base, other, field


def blob_payloads():
    """§6.7: *"Generated byte strings"*.

    A union rather than one `st.binary(0, 4096)`, and the corpus assertion is what forced it:
    hypothesis biases toward small values, so a single wide range produced nothing above **44
    bytes** in 200 draws. A store that reads with a fixed buffer round-trips a 44-byte blob
    perfectly, and `get(put(b)) == b` is the only assertion that would ever notice — so the large
    band has to be drawn deliberately rather than hoped for.

    `min_size=0` matters for the other end: an empty blob is a legal input to `put()` and the
    boundary where a content-addressed store built on "hash the bytes, skip if falsy" goes wrong.
    """
    return st.one_of(
        st.binary(min_size=0, max_size=64),
        st.binary(min_size=512, max_size=4096),
    )


#: The two writes `FR-STORE-04` requires in one transaction: *"a work unit's result and its ledger
#: status transition"*.
WRITE_KINDS: tuple[str, ...] = ("result", "status")


#: What happens after the first write of a transaction: it commits, or it is aborted.
#:
#: **The abort is the case, and its absence made the first draft unfalsifiable.** Every generated
#: transaction ran to completion, so both writes always landed and `has_result == has_status` was
#: trivially true for every interleaving. Review proved it: a `transaction()` that is a bare
#: `yield` — no BEGIN, no COMMIT, no rollback, two independent autocommit writes, zero atomicity —
#: passed 500/500 examples. `CT-STORE-03`'s claim is "both present or both absent **after any
#: crash**", and a corpus with no crash in it tests the half that was never in doubt.
OUTCOMES: tuple[str, ...] = ("commit", "abort")


@st.composite
def write_interleavings(draw) -> list[tuple[int, str, str]]:
    """§6.7: *"generated interleavings of result and status writes"*.

    Each entry is `(unit, first_write, outcome)`: which work unit, which of the two writes goes
    first inside the transaction, and whether that transaction commits or is aborted between them.
    The ordering half is what a naive implementation gets wrong; the abort half is what a
    non-transactional one gets wrong.
    """
    return draw(
        st.lists(
            st.tuples(
                st.integers(min_value=0, max_value=4),
                st.sampled_from(WRITE_KINDS),
                st.sampled_from(OUTCOMES),
            ),
            min_size=2,
            max_size=10,
        )
    )


# --- the FUZZ-04 reply generator (§6.7, added with #83) -----------------------------------------


#: The declared band set the `FUZZ-04` property's request carries — two bands, distinct
#: ordinals and descriptors. The generator and the property must agree on the set (a
#: valid reply names a band from it), so it is declared HERE and the property builds its
#: request from it — the `TC-JUDGE-09` shape.
FUZZ04_BANDS: tuple[tuple[str, int, str], ...] = (
    ("emerging", 0, "the criterion is partly met"),
    ("secure", 1, "the criterion is met"),
)
FUZZ04_BAND_NAMES: tuple[str, ...] = tuple(
    name for name, _ordinal, _descriptor in FUZZ04_BANDS
)
FUZZ04_ORDINALS = {name: ordinal for name, ordinal, _descriptor in FUZZ04_BANDS}

#: §6.7's arm column, verbatim. The valid arm is weighted x3 — the acceptance case must
#: dominate, or the property would pass against a parser that refuses everything (the
#: corpus guard asserts the acceptance arm never goes vacuous).
REPLY_ARMS: tuple[str, ...] = (
    "valid",
    "valid",
    "valid",
    "field-permuted",
    "missing",
    "extra",
    "wrong-types",
    "truncated-mid-token",
    "deeply-nested",
    "enormous-strings",
)

#: The "deeply nested" arm's ceiling. Bounded deliberately far below where CPython's
#: `json` scanner gives out: `json.loads` parses nesting to ~10,000 levels here and
#: raises `RecursionError` by ~50,000 — an interpreter-level stack exhaustion NO parser
#: code runs for, so no `MalformedResponseError` can name it. The plan's "deeply
#: nested" arm is generated where the reply CONTRACT, not the interpreter, is what
#: answers. 40 is still ~250x the depth the contract's five flat fields ever need.
MAX_REPLY_NESTING = 40

#: The "enormous strings" arm's ceiling, the same reading: an unbounded string is a
#: memory-exhaustion probe, not a reply shape the contract speaks about, and the
#: oracle — the exception channel — needs the string bounded to stay fast.
MAX_REPLY_STRING = 4096

#: Inventory assessments for the valid arm — every one names the evidence channel (span
#: vocabulary, or the `excerpt` mark), so none can trip the prose-only gate
#: (`FR-JUDGE-10`) and the valid arm stays a pure acceptance case.
_INVENTORY_ASSESSMENTS: tuple[str, ...] = (
    "the cited spans support the band",
    "the cited span covers the claimed condition",
    "the cited excerpt shows the band holds",
)

#: One wrong-typed value per reply field — every entry must refuse. The pools are drawn
#: so none can parse by accident: a `cited_spans` scalar or mapping is not a sequence
#: (`_sequence_of` refuses bare scalars; `None` would be the LEGAL empty inventory, so
#: it is not drawn here), a non-string assessment/band, a non-bool sufficiency (an int
#: 1 is NOT a bool), a non-number confidence (bools excluded explicitly).
_WRONG_TYPES = {
    "cited_spans": st.sampled_from((0, 1, 3.5, True, False, "span", {"start": 0})),
    "evidence_assessment": st.sampled_from((42, True, None, [], {})),
    "evidence_sufficient": st.sampled_from((1, 0, "yes", None, 0.5, [])),
    "band": st.sampled_from((42, True, None, [], "")),
    "self_confidence": st.sampled_from(("0.5", True, False, None, [])),
}

#: The value the "deeply nested" arm wraps. Plain scalars only: a whitelisted span
#: mapping nested once would parse as a LEGAL single-span inventory, so no dict is
#: drawn here.
_NESTED_BASES = st.sampled_from((1, "x", True, None))


@st.composite
def _span_inventories(draw):
    """A cited-span inventory: none (the uncited verdict, `FR-JUDGE-12`), one, or two
    spans over a small offset pool — shapes inside `_span_of`'s whitelist."""
    count = draw(st.sampled_from((0, 1, 1, 2)))
    spans = []
    for _ in range(count):
        start = draw(st.integers(min_value=0, max_value=32))
        spans.append(
            {
                "start": start,
                "end": start + draw(st.integers(min_value=1, max_value=8)),
                "text": draw(st.sampled_from(("the cited evidence", "a quoted line", "x"))),
            }
        )
    return spans


def _expected_verdict(reply: dict) -> dict:
    """The verdict fields a VALID reply must parse to, as the parser returns them:
    the band, the DECLARED ordinal for it (never a guessed position), the confidence
    as a float, and the assessment/sufficiency/spans verbatim."""
    return {
        "band": reply["band"],
        "ordinal": FUZZ04_ORDINALS[reply["band"]],
        "confidence": float(reply["self_confidence"]),
        "assessment": reply["evidence_assessment"],
        "sufficient": reply["evidence_sufficient"],
        "spans": tuple(reply["cited_spans"]),
    }


def _string_interiors(text: str) -> list[tuple[int, int]]:
    """The `(first_interior_byte, closing_quote_index)` range of every JSON string
    literal in `text` — the fixture replies' keys and values are escape-free ASCII, so
    quote toggling is exact."""
    interiors: list[tuple[int, int]] = []
    open_at: int | None = None
    for index, ch in enumerate(text):
        if ch == '"':
            if open_at is None:
                open_at = index + 1
            else:
                interiors.append((open_at, index))
                open_at = None
    return interiors


@st.composite
def _mid_token_truncations(draw, reply_text: str) -> str:
    """The reply cut INSIDE a string literal — `truncated mid-token`, where a parser
    must refuse on the decode, never on a structure check it never reached."""
    start, close = draw(st.sampled_from(_string_interiors(reply_text)))
    cut = draw(st.integers(min_value=start, max_value=close))
    return reply_text[:cut]


@st.composite
def judge_replies(draw):
    """One generated judge reply: `(text, kind, expected)`.

    `text` is the exact wire form the parser reads; `kind` is which of §6.7's eight
    arms produced it; `expected` is `None` for the six refusal arms (the reply MUST
    raise `MalformedResponseError`) and the expected verdict fields for the two
    acceptance cases (the reply MUST parse, and to the fields it carried) — the
    property pins the direction, not only the channel.

    The valid arm varies band, confidence, sufficiency, assessment and span inventory
    over small pools: an acceptance that ignores any field still has to round-trip
    what the reply carried. The permutation arm draws a non-identity order of the five
    pinned fields (the order check's own case); the missing/extra arms break the
    five-key shape; the truncated arm cuts inside a string literal; the nesting arm
    wraps a scalar to the plan's depth bound; the enormous arm overflows one field's
    string — the assessment, which the contract does NOT bound (so the verdict
    round-trips it), or the band, which no declared set contains (refusal).
    """
    kind = draw(st.sampled_from(REPLY_ARMS))
    reply = {
        "cited_spans": draw(_span_inventories()),
        "evidence_assessment": draw(st.sampled_from(_INVENTORY_ASSESSMENTS)),
        "evidence_sufficient": draw(st.booleans()),
        "band": draw(st.sampled_from(FUZZ04_BAND_NAMES)),
        "self_confidence": draw(st.sampled_from((0.05, 0.5, 0.62, 0.95))),
    }
    if kind == "valid":
        return json.dumps(reply), kind, _expected_verdict(reply)
    if kind == "field-permuted":
        order = draw(
            st.permutations(list(reply)).filter(lambda seq: list(seq) != list(reply))
        )
        return json.dumps({name: reply[name] for name in order}), kind, None
    if kind == "missing":
        dropped = draw(st.sampled_from(list(reply)))
        broken = {name: value for name, value in reply.items() if name != dropped}
        return json.dumps(broken), kind, None
    if kind == "extra":
        broken = dict(reply)
        broken[draw(st.sampled_from(("band_points", "verdict", "score", "notes")))] = draw(
            st.sampled_from((1, "x", True, None))
        )
        return json.dumps(broken), kind, None
    if kind == "wrong-types":
        field = draw(st.sampled_from(list(reply)))
        broken = dict(reply)
        broken[field] = draw(_WRONG_TYPES[field])
        return json.dumps(broken), kind, None
    if kind == "truncated-mid-token":
        return draw(_mid_token_truncations(json.dumps(reply))), kind, None
    if kind == "deeply-nested":
        field = draw(st.sampled_from(list(reply)))
        broken = dict(reply)
        value = draw(_NESTED_BASES)
        for _ in range(draw(st.integers(min_value=2, max_value=MAX_REPLY_NESTING))):
            value = [value]
        broken[field] = value
        return json.dumps(broken), kind, None
    # enormous-strings: the assessment arm accepts (nothing in the contract bounds the
    # assessment's length, so the verdict must carry it verbatim); the band arm refuses
    # (a multi-kilobyte name is not a declared band).
    field = draw(st.sampled_from(("evidence_assessment", "band")))
    broken = dict(reply)
    broken[field] = draw(
        st.text(
            alphabet="qxzvkjbnmw",
            min_size=draw(st.integers(min_value=256, max_value=MAX_REPLY_STRING)),
            max_size=MAX_REPLY_STRING,
        )
    )
    if field == "band":
        return json.dumps(broken), kind, None
    return json.dumps(broken), kind, _expected_verdict(broken)
